// Process single item
const item = $input.item.json;
const callId = item.callid || 'unknown';
const billsec = item.billsec || 0;

console.log(`⚠️ Call ${callId} skipped - call duration (billsec: ${billsec})`);

return {
  json: {
    ...item,
    skipped: true,
    skip_reason: 'call duration <= 15 sec'
  }
};

// Prompt oluştur
// Conversation verisini al
let conversation;
let callid_from_input = 'unknown';
try {
  const convNodeOutput = $input.first().json; // Process Conversation'dan gelen veri
  conversation = convNodeOutput.conversation || [];
  callid_from_input = convNodeOutput.callid || 'unknown';
  if (!Array.isArray(conversation)) {
    console.log('Uyarı: conversation bir array değil');
    conversation = [];
  }
} catch (error) {
  console.log('Hata (Create Analysis Prompt - conversation):', error.message);
  conversation = [];
}

// Prompt oluştur
const promptsystem = `
You are a call center conversation analyzer.

Below is a JSON array called \`conversation\`, where each item represents a speech block with the following structure:
{
  "speaker": "speaker_0" or "speaker_1" or "unknown",
  "text": "spoken words",
  "start": float (start time in seconds),
  "end": float (end time in seconds),
  "conversation_index": integer (order of conversation)
}

Your task is to analyze this conversation based on the following criteria. Respond with true, false, or "unknown" for boolean questions. For the sale value scale, use an integer from 1 to 5 if a sale occurred, otherwise use 0 or null.

Instructions:
1.  Determine which speaker is the **call center agent** and which is the **customer**.
2.  Analyze the **customer's emotional tone** (e.g., calm, angry, excited, confused, etc.).
3.  Assess overall **conversation sentiment** (positive, negative, neutral).
4.  Identify the **main topic** (e.g., complaint, sales, technical issue, billing).
5.  Extract the **most significant term/keyword** (e.g., 'approved', 'canceled', 'offer', 'refund').
6.  Classify the **general experience** (acceptable, unacceptable, neutral).
7.  Summarize **customer's experience in one word** (e.g., frustrating, smooth, excellent).
8.  Was an **email address asked for or provided**?
9.  Did any **positive comments from the customer lead to or reinforce a sale/commitment**?
10. Did any **negative comments from the customer prevent or hinder a sale/commitment**?
11. Was there any **price negotiation**?
12. Was the **customer addressed politely** (e.g., using their name, polite phrases)?
13. Did the conversation seem **lighthearted or fun** at any point?
14. Were the **advantages of the services/products clearly mentioned** to the customer?
15. Were **competing platforms or services (other than Google's own, if applicable) mentioned**?
16. Was a **sale or commitment made** by the customer? (successful, unsuccessful, not_applicable)
17. If a sale was made, **rate its significance or value on a scale of 1 (low) to 5 (high)**.
18. Was the customer asked if they **knew any of the people who left reviews/comments** (if reviews were discussed)?
19. Were **advantages of a premium/high-level profile or service tier mentioned**?

If the conversation array is empty or analysis cannot be performed, return a valid JSON object with all fields set to "unknown" or null as appropriate, and include an "llm_error_message" field with a short explanation (e.g., "Insufficient data for analysis" or "Empty conversation transcript").

Return the result in only this JSON format (ensure valid JSON, no markdown, boolean values as true/false not strings "true"/"false"):

{
  "sentiment": "<positive|negative|neutral|unknown>",
  "topic": "<conversation_topic|unknown>",
  "significant_term": "<most_relevant_keyword|unknown>",
  "general_value": "<acceptable|unacceptable|neutral|unknown>",
  "general_experience": "<one_word_summary|unknown>",
  "email_inquired": "<true|false|unknown>",
  "positive_comment_passed_sale": "<true|false|unknown>",
  "negative_comment_passed_sale": "<true|false|unknown>",
  "price_negotiated": "<true|false|unknown>",
  "customer_addressed_politely": "<true|false|unknown>",
  "conversation_fun": "<true|false|unknown>",
  "service_advantages_mentioned": "<true|false|unknown>",
  "other_platforms_mentioned": "<true|false|unknown>",
  "sale_outcome": "<successful|unsuccessful|not_applicable|unknown>",
  "sale_value_scale": "<integer_0_to_5|null>",
  "asked_if_commenters_known": "<true|false|unknown>",
  "high_profile_advantages_mentioned": "<true|false|unknown>",
  "llm_error_message": "<error_message_if_any_or_null>"
}
`;

const promptuser = `

Here is the JSON transcript to analyze:

${JSON.stringify(conversation, null, 2)}
`;

// Sonucu döndür
return [{ json: { ...$input.item.json, promptsys: promptsystem, promtuser : promptuser } }];

// Cron tetiklendiğinde başlangıç mesajı
const now = new Date().toISOString();
console.log(`🔄 Call Center Analysis Cron started at ${now}`);

return [{
  json: {
    timestamp: now,
    message: "Cron job başlatıldı - işlenmemiş call kayıtları kontrol ediliyor"
  }
}];

// İşlem tamamlandığında log mesajı
const item = $input.first();
const callId = item.json.callid || $('Prepare S3 Download').item.json.callid || 'unknown';
const status = item.json.error ? 'error' : 'success';

if (status === 'success') {
    console.log(`✅ Call ${callId} processed successfully.`);
} else {
    console.log(`⚠️ Call ${callId} processed with error: ${item.json.error_message || item.json.error}`);
}

// Loop için sinyal döndür
return [{
  json: {
    status: status,
    callid: callId,
    message: status === 'success' ? "Kayıt başarıyla işlendi" : "Kayıt hata ile işlendi"
  }
}];

// Hata durumunda oluşan verileri işleyen fonksiyon
const item = $input.first(); // Bu item IF STT/Conv Error? (True) -> Process Conversation'dan gelir
let callId = item.json.callid || 'unknown';
let errorMessage = item.json.error || 'Bilinmeyen STT/Conversation işleme hatası';

// Hata bilgisini logla
console.log(`İşleme hatası (STT/Conv): CallID=${callId}, Hata=${errorMessage}`); 

return [
  {
    json: {
      callid: callId,
      processed: true, 
      error: true,
      error_message: errorMessage.substring(0, 250) // Mesajı DB için kısalt
    }
  }
];

// Elevanlabs STT'den words değerini al
let words = [];
let sttError = null;

const inputItem = $input.first();
if (inputItem.json.error) {
  sttError = inputItem.json.error.message || 'ElevenLabs STT bilinmeyen hata';
  console.log('Hata: elevanlabs STT node hatası:', sttError);
} else {
  try {
    const elevenlabsOutput = inputItem.json;
    if (elevenlabsOutput && elevenlabsOutput.words && Array.isArray(elevenlabsOutput.words)) {
      words = elevenlabsOutput.words;
    } else {
      sttError = 'Transkripsiyon verisi (words dizisi) bulunamadı veya array değil';
      console.log('Uyarı:', sttError);
    }
  } catch (error) {
    sttError = 'elevanlabs STT çıktısı parse edilemedi: ' + error.message;
    console.log('Hata:', sttError);
  }
}

// Çağrı ID'sini al
let callid = 'unknown';
try {
  callid = $('Prepare S3 Download').item.json.callid || 'unknown';
} catch (error) {
  console.log('Uyarı: callid Prepare S3 Download nodeundan alınamadı:', error.message);
}

if (sttError) {
  return [
    {
      json: {
        callid: callid,
        conversation: [],
        error: sttError // Hata bilgisini sonraki adıma taşı
      }
    }
  ];
}

// Zaman sırasına göre sırala
const sortedWords = words.sort((a, b) => a.start - b.start);

const conversation = [];
let currentSpeaker = null;
let currentText = '';
let currentStart = null;
let currentEnd = null;
let conversationIndex = 0;

for (const word of sortedWords) {
  const speaker = word.speaker_id === undefined || word.speaker_id === null ? 'unknown' : `speaker_${word.speaker_id}`;
  const text = word.text || '';

  if (speaker !== currentSpeaker) {
    if (currentSpeaker !== null && currentText.trim() !== '') {
      conversation.push({
        speaker: currentSpeaker,
        text: currentText.trim(),
        start: currentStart,
        end: currentEnd,
        conversation_index: conversationIndex++
      });
    }
    currentSpeaker = speaker;
    currentText = text;
    currentStart = word.start;
    currentEnd = word.end;
  } else {
    currentText += ' ' + text;
    currentEnd = word.end;
  }
}

if (currentSpeaker !== null && currentText.trim() !== '') {
  conversation.push({
    speaker: currentSpeaker,
    text: currentText.trim(),
    start: currentStart,
    end: currentEnd,
    conversation_index: conversationIndex++
  });
}

return [
  {
    json: {
      callid: callid,
      conversation: conversation
    }
  }
];

// Call bilgilerini al ve S3 path oluştur
const item = $input.first();
const callData = item.json;

// Log için
console.log('Processing call:', callData.callid);

// S3 key oluştur - call_direction ve callid kullanarak
let s3Key = '';
if (callData.call_direction) {
  s3Key = `calls/${callData.call_direction.toLowerCase()}/${callData.callid}.wav`; // Ensure direction is lowercase for consistency
} else if (callData.s3_path) {
  // Mevcut s3_path'ten key çıkar
  s3Key = callData.s3_path.replace('s3://callintech/', '');
} else {
  // call_direction yoksa ve s3_path yoksa, URL'den çıkarmayı dene (CALL_CENTER_S3_UPLOAD.json'daki mantığa benzer)
  if (callData.file_url && callData.file_url.toLowerCase().includes("inbound")) {
    s3Key = `calls/inbound/${callData.callid}.wav`;
  } else if (callData.file_url && callData.file_url.toLowerCase().includes("outbound")) {
    s3Key = `calls/outbound/${callData.callid}.wav`;
  } else {
    // Varsayılan olarak inbound kabul et veya hata ver
    console.warn('Call direction could not be determined for S3 key, defaulting to inbound for callid:', callData.callid);
    s3Key = `calls/inbound/${callData.callid}.wav`; 
  }
}

console.log('S3 Key:', s3Key);

return [{
  json: {
    ...callData,
    Key: s3Key
  }
}];

